#!/usr/bin/env bash
# Apply this fork's Client model (classes, funnel type, My Clients navigator) on production.
# Official workspace/transactor images do not include Client; SQL is generated by
# scripts/huly-local-apply-fork-model.mjs --dump-sql and uploaded next to this script.
set -euo pipefail
cd /opt/huly-selfhost
source huly_v7.conf
URL_LOCAL=$(echo "$CR_DB_URL" | sed 's/@cockroach:/@127.0.0.1:/')"?sslmode=disable"
SQL="${1:-/tmp/huly-client-model.sql}"
[[ -f "$SQL" ]] || { echo "Missing $SQL"; exit 1; }

docker cp "$SQL" huly_v7-cockroach-1:/tmp/huly-client-model.sql
docker exec huly_v7-cockroach-1 ./cockroach sql --url "$URL_LOCAL" -f /tmp/huly-client-model.sql

echo '==== restart workspace + transactor ===='
docker restart huly_v7-workspace-1 huly_v7-transactor-1
sleep 12
docker restart huly_v7-nginx-1
echo '==== client model patch done ===='
